"""Pass 5: Chenoweth & Stephan (2011), chapter 4 'The Iranian Revolution, 1977-1979', read in full."""
from common import *
from d_review import get, setp, addp, addl, N

CS = N['cs']; KZ = src('Kurzman, C. (2004). The Unthinkable Revolution in Iran')

new('lesson-1357', T('۱۳۵۷ از دریچهٔ مقاومتِ مدنی: چرا برد، و چرا بعدش دموکراسی نشد', '1979 through the civil-resistance lens: why it won, and why democracy did not follow'),
    T('چنووت و استفان انقلابِ ۱۳۵۷ را نمونهٔ یک کارزارِ «موفقِ» خشونت‌پرهیز می‌دانند: چریک‌ها شکست خوردند و اعتصاب و عدمِ همکاریِ توده‌ای ستون‌های شاه را برداشت. اما همین نمونه معمای بزرگِ کتاب است: کارزارِ خشونت‌پرهیزِ پیروز به حکومتی دینیِ سرکوبگر رسید. هر دو نیمه درسِ مستقیم برای امروزند.',
      'Chenoweth and Stephan treat 1979 as a successful nonviolent campaign: the guerrillas failed and mass strikes and non-cooperation removed the Shah\'s pillars. Yet the same case is the book\'s great puzzle: a winning nonviolent campaign produced a repressive theocracy. Both halves are direct lessons for today.'),
    [P('یادداشتِ ویراستار: فصلِ چهارمِ کتابِ «چرا مقاومتِ مدنی کار می‌کند» (انقلابِ ایران، ۱۹۷۷–۱۹۷۹) کامل خوانده شد. فصل خودش بیشتر بر کورزمن تکیه دارد؛ هر جا عدد از کورزمن است، گفته شده.', 'Editor note: chapter 4 of Why Civil Resistance Works (the Iranian Revolution) was read in full; it leans heavily on Kurzman, noted where numbers come from him.', [CS], True),
     P('چریک‌ها در برابرِ توده: گروه‌های مسلح (فدائیان، مجاهدین) از ۱۳۴۹ تا ۱۳۵۷ هرگز بیش از حدودِ پنجاه هزار عضو نداشتند، در سرکوبِ ۱۳۵۵ از هم پاشیدند و میانِ خودشان هم خونریزی داشتند. فشارِ اصلی از اعتراض، اعتصابِ سراسری و عدمِ همکاری آمد که موانعِ پیوستن (جسمی، اخلاقی، تعهدی) را پایین آورد و از هر قشری آدم آورد.', 'Guerrillas versus the mass: armed groups never exceeded about fifty thousand members, collapsed under the 1976 counterinsurgency and fought among themselves. The real pressure came from protest, general strike and non-cooperation, which lowered the barriers to joining.', [CS]),
     P('پراکندگی به‌جای تمرکز: بعد از کشتارها، رهبریِ جنبش دو بار (خرداد ۱۳۵۷ و پس از ۱۷ شهریور) خیابان را تعطیل کرد و به «در خانه ماندن»، تحریم، و شعار از پشتِ بام رو آورد؛ مشارکت بالا ماند و هزینهٔ جانی پایین آمد. در زبانِ بازی: حرکتِ «می‌آیم» لازم نیست همیشه خیابان باشد؛ ارزان‌ترین شکلِ پس‌گرفتنِ همکاری را باید در دسترس گذاشت.', 'Dispersion instead of concentration: after massacres the leadership twice halted street protests in favour of stay-aways, boycotts and rooftop chanting; participation stayed high and the death toll fell. In game terms, "I come" need not always mean the street.', [CS, KZ]),
     P('اعتصابِ چرخشی و ناتوانیِ دولت: از ۱۸ شهریور ۱۳۵۷ اعتصاب از پالایشگاه‌ها شروع شد و تا آبان تقریباً همهٔ بخش‌ها (بانک، هواپیمایی، گمرک، برق، روزنامه) را گرفت؛ صادراتِ نفت در دو هفته از بیش از ۵ به کمتر از ۲ میلیون بشکه رسید. وقتی ارتش کارگران را به زور برمی‌گرداند، الگو این بود: سرِ کار برگشتن، و دوباره اعتصاب. به نقلِ کورزمن، فرماندهان در دی ۱۳۵۷ بازداشتِ صد هزار نفر را بررسی کردند ولی زندان‌ها فقط جای پنج هزار نفرِ دیگر داشتند. هیچ دستگاهِ سرکوبی برای نافرمانیِ همگانی ساخته نشده است.', 'Rolling strikes and state incapacity: strikes began at the refineries in September 1978 and by November covered nearly every sector; oil exports fell from over 5 to under 2 million barrels a day in two weeks. Forced back, workers struck again. Per Kurzman, commanders considered arresting 100,000 but jails had room for 5,000 more.', [CS, KZ]),
     P('خنثی‌کردنِ نیروهای امنیتی با برادری نه دشمنی: گل در لولهٔ تفنگ، شعارِ «ارتش جزوِ ملت است»، شبکهٔ کمک به فراریان؛ فرار تا رفتنِ شاه کم ماند، اما روحیه فرو ریخت و به نقلِ کورزمن رئیسِ ستادِ ارتش در دی ۱۳۵۷ توانِ ارتش را حدودِ ۵۵٪ برآورد کرد. و شرطِ آن روشن بود: سربازها به معترضان می‌گفتند اگر خشونت نکنید ما هم شلیک نمی‌کنیم.', 'Neutralising security forces through fraternisation, not enmity: flowers in rifles, "the army is part of the nation", help for deserters. Desertions stayed low until the Shah left, but morale collapsed (per Kurzman, about 55 percent capacity in January 1979). The condition was explicit: soldiers would not shoot if protesters stayed nonviolent.', [CS, KZ]),
     P('شبکه: بیش از نُه هزار مسجد و به نقلِ رَسلر دوازده هزار هیئتِ مذهبی فقط در تهران، با پیوندِ بازار و روحانیت، و نوارِ کاست. این شبکهٔ غیرمتمرکز هماهنگی را ممکن کرد. تفاوتِ امروز: آن شبکه حالا در دستِ حکومت است و شهر شبکهٔ جایگزین ندارد؛ این همان کمبودی است که «ده نقشِ نساخته» باید پر کنند.', 'Network: over nine thousand mosques and, per Rasler, twelve thousand religious associations in Tehran alone, with the bazaar-clergy link and cassette tapes. Today that network belongs to the state and the city has no substitute, the gap the ten unbuilt roles must fill.', [CS]),
     P('چرا بعدش دموکراسی نشد (معمای کتاب): (۱) ایدئولوژیِ کارزار قدرت را در یک نفر جمع می‌کرد؛ (۲) ائتلاف بر «نه به شاه» متحد بود ولی هیچ تصویرِ مشترکی از فردا نداشت، و ابهامِ عمدی دربارهٔ «حکومتِ اسلامی» هم جمع‌کننده بود و هم بذرِ دعوای بعد؛ (۳) رهبریِ تبعیدی و کاریزما به‌جای تعهدِ چندجانبه به ساختنِ دولت؛ (۴) جناحِ مسلح بهانهٔ تصفیه داد. سرانجام: دو دولت هم‌زمان در بهمن ۱۳۵۷، دولتِ موقت در چند ماه کنار گذاشته شد، و به گفتهٔ کتاب نزدیک به ۲۰ هزار نفر در دورهٔ پس از انقلاب کشته شدند (جمهوری اسلامی ۱۲ هزار را می‌پذیرد) و در ۱۳۶۷ هزاران زندانیِ سیاسی اعدام شدند.', 'Why democracy did not follow: the ideology concentrated power in one person; the coalition united on "no to the Shah" with no shared picture of tomorrow, the deliberate ambiguity both uniting and seeding the later fight; exile leadership and charisma rather than a multi-party commitment to build a state; the armed fringe gave a pretext for purges.', [CS], True),
     P('درس برای برنامهٔ سیمرغ، هر چهار تا مستقیم: میثاقِ مکتوب پیش از سقوط، نه بعد (پاسخ به ۲)؛ «معیارِ عمومی برای هر مدعیِ رهبری» و تاریخِ همه‌پرسیِ تغییرناپذیر (پاسخ به ۱ و ۳)؛ انضباطِ خشونت‌پرهیز که بهانهٔ تصفیه ندهد (پاسخ به ۴)؛ و نهادهایی که بعد از روزِ سقوط هم کار کنند (شبکهٔ جایگزین). چنووت و استفان یادآوری می‌کنند که ایران استثناست: بیشترِ کارزارهای خشونت‌پرهیز، حتی شکست‌خورده‌ها، بعدها به دموکراسی نزدیک‌ترند تا کارزارهای مسلح.', 'Lessons for the Simorgh plan: a written covenant before the fall; a public standard for any claimant to leadership and a fixed referendum date; nonviolent discipline that gives no pretext for purges; institutions that keep working after the fall. Iran is the exception: most nonviolent campaigns, even failed ones, end closer to democracy than armed ones.', [CS], True)],
    [L('simorgh:seven-nights', 'هفت شب', 'Seven nights'), L('simorgh:clerical-rise', 'هشت پله', 'Eight steps'), L('simorgh:pre-mortem', 'پیش‌مرگ', 'Pre-mortem'),
     L('simorgh:pillars-of-support', 'ستون‌ها', 'Pillars'), L('simorgh:covenantal-transition', 'گذارِ میثاقی', 'Covenantal transition')], 'simorgh:history')

addp('seven-nights', P('برای شبِ یکم ببین «۱۳۵۷ از دریچهٔ مقاومتِ مدنی»: چنووت و استفان نشان می‌دهند همان کارزارِ خشونت‌پرهیزی که شاه را برداشت، چون تصویرِ مشترکی از فردا نداشت و قدرت را در یک نفر جمع کرد، به ضحّاکِ تازه رسید.', 'For night one see the 1979 lesson entry: the nonviolent campaign that removed the Shah, lacking a shared picture of tomorrow and concentrating power in one person, produced a new Zahhak.', [CS]), at=1)
addp('pillars-of-support', P('شاهد از خودِ ایران (۱۳۵۷): برادری با سرباز (گل، «ارتش جزوِ ملت است») روحیهٔ ارتش را فرو ریخت؛ اعتصابِ چرخشی دولت را از کار انداخت چون سرباز نمی‌تواند پالایشگاه و نیروگاه را بچرخاند؛ و رئیسِ ستاد توانِ ارتش را حدودِ ۵۵٪ برآورد کرد. شرطِ همهٔ این‌ها خشونت‌پرهیز ماندنِ جنبش بود.', 'Evidence from Iran itself (1979): fraternisation broke army morale; rolling strikes disabled the state since soldiers cannot run refineries; army capacity about 55 percent. All conditional on the movement staying nonviolent.', [CS, KZ]), at=2)
addp('game-rules-v2', P('افزوده از درسِ ۱۳۵۷ (حرکتِ «در خانه»): در هر روز، بازیکنِ شهر به‌جای «می‌آیم» می‌تواند «در خانه» بگذارد: نصفِ وزنِ «می‌آیم» را دارد ولی سرکوبِ شب نمی‌تواند هدفش بگیرد. این حرکت مشارکتِ کم‌خطر را مدل می‌کند، همان که در ۱۳۵۷ بعد از کشتارها جنبش را زنده نگه داشت.', 'Added from 1979 (the stay-home move): a citizen may play "at home" instead of "I come": half the weight, but immune to the night\'s repression. Models low-risk participation that kept the 1979 movement alive after massacres.', [CS]), at=4)
addp('pre-mortem', P('شاهدِ تاریخی برای حالتِ ۹ (فردمحوری): در ۱۳۵۷ کارزار پیروز شد ولی چون ایدئولوژی‌اش قدرت را در یک نفر جمع می‌کرد و ائتلاف تصویرِ مشترکی از فردا نداشت، دولتِ موقت در چند ماه کنار رفت. یعنی خطرِ ۹ فرضی نیست؛ یک بار در همین کشور رخ داده است.', 'Historical evidence for mode 9: in 1979 the campaign won, but power concentrated in one person and no shared picture of tomorrow meant the provisional government fell within months.', [CS], True))
addp('why-not-january', P('مقایسه با ۱۳۵۷: آن بار اعتصابِ سراسری ماه‌ها ادامه داشت (از شهریور تا بهمن)، کارگران پس از هر بازگرداندنِ اجباری دوباره اعتصاب کردند، و شبکهٔ مسجد و بازار هماهنگی را بدونِ نیاز به رسانهٔ آزاد نگه داشت. در دی ۱۴۰۴ هیچ‌کدام از این سه نبود: اعتصابِ پایدار، صندوق، و شبکهٔ آفلاین.', 'Compared with 1979: then the general strike lasted months, workers struck again after each forced return, and the mosque-bazaar network sustained coordination without free media. In January 2026 none of the three existed.', [CS, KZ], True))
addl('two-irans', L('simorgh:lesson-1357', '۱۳۵۷ از دریچهٔ مقاومتِ مدنی', '1979 civil-resistance lesson'))
